<?php
namespace App\Controllers; use App\Helpers\View; use App\Middlewares\AdminMiddleware; use App\Config\Database;
final class AdminController {public function dashboard():void{AdminMiddleware::handle();$p=Database::connection();$metrics=['products'=>$p->query('SELECT COUNT(*) FROM products')->fetchColumn(),'clients'=>$p->query("SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='COMPRADOR'")->fetchColumn(),'orders'=>$p->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'pending'=>$p->query("SELECT COUNT(*) FROM orders o JOIN order_statuses s ON s.id=o.status_id WHERE s.name='PENDIENTE'")->fetchColumn(),'sales'=>$p->query('SELECT COALESCE(SUM(total),0) FROM orders')->fetchColumn(),'points'=>$p->query("SELECT COALESCE(SUM(points),0) FROM point_movements WHERE type='EARN'")->fetchColumn()];View::render('admin/dashboard',['title'=>'Panel administrativo','metrics'=>$metrics]);}}
